"""Telemetry setup, as generated by Agents CLI. Standard library only at import time."""
from __future__ import annotations

import logging
import os


def setup_telemetry() -> str | None:
    """Configure OpenTelemetry for GenAI prompt-response logging.

    When LOGS_BUCKET_NAME is set, completions are uploaded to
    gs://<bucket>/completions as JSON lines and surface in BigQuery through the
    external table in deployment/terraform/telemetry.tf.
    """
    os.environ.setdefault("GOOGLE_CLOUD_AGENT_ENGINE_ENABLE_TELEMETRY", "true")
    bucket = os.environ.get("LOGS_BUCKET_NAME")
    capture_content = os.environ.get("OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT", "false")
    if bucket and capture_content != "false":
        logging.info("Prompt-response logging enabled - mode: NO_CONTENT (metadata only, no prompts/responses)")
        os.environ.setdefault("OTEL_SEMCONV_STABILITY_OPT_IN", "gen_ai_latest_experimental")
        os.environ.setdefault("OTEL_INSTRUMENTATION_GENAI_COMPLETION_HOOK", "upload")
        os.environ.setdefault("OTEL_INSTRUMENTATION_GENAI_UPLOAD_FORMAT", "jsonl")
        os.environ.setdefault("OTEL_INSTRUMENTATION_GENAI_UPLOAD_BASE_PATH", f"gs://{bucket}/completions")
    else:
        logging.info("Prompt-response logging disabled")
    return bucket
